  g.beginPath(); g.moveTo(sx, cy + V(6, 5)); g.lineTo(sx, cy - V(58, 48)); g.stroke();
  g.beginPath(); g.moveTo(sx, cy - V(58, 48)); g.quadraticCurveTo(sx + V(40, 34), cy - V(58, 48), sx + V(40, 34), cy - V(26, 22)); g.stroke();
  // kettle on the hob
  const kx = E.W * 0.86, ky = cy - V(2, 2), kr = V(46, 38);
